import app from 'flarum/forum/app';
import Notification from 'flarum/forum/components/Notification';
import { t } from '../common';

/** To everyone who helped: the goal was reached. */
export default class GoalReachedNotification extends Notification {
  icon() {
    return 'fas fa-flag-checkered';
  }
  href() {
    return app.route('community-goals');
  }
  content() {
    const data = this.attrs.notification.content() || {};
    return t('notification.reached', {
      title: data.title
    });
  }
  excerpt() {
    const data = this.attrs.notification.content() || {};
    return data.reward || null;
  }
}
flarum.reg.add('ernestdefoe-community-goals', 'forum/components/GoalReachedNotification', GoalReachedNotification);